// A Verus‐verified implementation of linear search over a Vec<i32>.
//
// Properties:
// - If `ret >= 0`, then
//     * `ret < nums.len()`,
//     * `nums[ret] == target`,
//     * and for all `j < ret`, `nums[j] != target`.
//   Thus the returned index is the first occurrence of `target`.
// - If `ret < 0`, then for all `j < nums.len()`, `nums[j] != target`.
// - Always `ret < nums.len()` (vacuous when `ret < 0`).

use vstd::prelude::*;

verus! {

    pub fn linear_search(nums: Vec<i32>, target: i32) -> (ret: i32)
        // We assume the vector length fits in a 32‐bit signed integer.
        requires nums.len() <= i32::MAX as usize,
        // Always: ret < nums.len() as i32.
        ensures ret < nums.len() as i32,
        // If ret >= 0, it is the first index where nums[ret] == target.
        ensures if ret >= 0 {
            let idx = ret as usize;
            idx < nums.len() &&
            nums[idx] == target &&
            forall |j: usize| j < idx ==> nums[j] != target
        // Otherwise, target does not occur anywhere.
        } else {
            forall |j: usize| j < nums.len() ==> nums[j] != target
        }
    {
        let mut i: usize = 0;
        // Loop invariant: all positions < i do not contain target.
        // And i never exceeds nums.len().
        while i < nums.len()
            invariant i <= nums.len(),
            invariant forall |j: usize| j < i ==> nums[j] != target,
            decreases nums.len() - i
        {
            if nums[i] == target {
                // Found the first occurrence, return its index.
                return i as i32;
            }
            i += 1;
        }
        // Not found: return a negative value.
        -1
    }

}